-- CAN1400: the social policy tree of Paradise Found plus a faith and a trade branch in place of the nine stock branches (generated by tools/paradise_policies.py).
-- The three Brave New World ideologies and their tenets stay; the Industrial era that triggers them is unreachable.
DELETE FROM Policies WHERE PolicyBranchType IN ('POLICY_BRANCH_TRADITION', 'POLICY_BRANCH_LIBERTY', 'POLICY_BRANCH_HONOR', 'POLICY_BRANCH_PIETY', 'POLICY_BRANCH_PATRONAGE', 'POLICY_BRANCH_AESTHETICS', 'POLICY_BRANCH_COMMERCE', 'POLICY_BRANCH_EXPLORATION', 'POLICY_BRANCH_RATIONALISM') OR Type IN (SELECT FreePolicy FROM PolicyBranchTypes WHERE Type IN ('POLICY_BRANCH_TRADITION', 'POLICY_BRANCH_LIBERTY', 'POLICY_BRANCH_HONOR', 'POLICY_BRANCH_PIETY', 'POLICY_BRANCH_PATRONAGE', 'POLICY_BRANCH_AESTHETICS', 'POLICY_BRANCH_COMMERCE', 'POLICY_BRANCH_EXPLORATION', 'POLICY_BRANCH_RATIONALISM')) OR Type IN (SELECT FreeFinishingPolicy FROM PolicyBranchTypes WHERE Type IN ('POLICY_BRANCH_TRADITION', 'POLICY_BRANCH_LIBERTY', 'POLICY_BRANCH_HONOR', 'POLICY_BRANCH_PIETY', 'POLICY_BRANCH_PATRONAGE', 'POLICY_BRANCH_AESTHETICS', 'POLICY_BRANCH_COMMERCE', 'POLICY_BRANCH_EXPLORATION', 'POLICY_BRANCH_RATIONALISM'));
